import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("expected IllegalArgumentException");
    }

    public static void main(String[] args) {
        check(Solution.runPipeline(" unchanged ", List.of()).equals(" unchanged "), "empty pipeline must preserve input exactly");
        ArrayList<String> commands = new ArrayList<>(List.of("trim", "upper", "reverse", "take:3", "lower"));
        check(Solution.runPipeline("  abCd  ", commands).equals("dcb"), "ordered pipeline result incorrect");
        check(commands.equals(List.of("trim", "upper", "reverse", "take:3", "lower")), "commands were mutated");

        check(Solution.runPipeline("abcdef", List.of("take:0")).equals(""), "take zero failed");
        check(Solution.runPipeline("abc", List.of("take:3")).equals("abc"), "take exact length failed");
        check(Solution.runPipeline("abc", List.of("take:999999999999999999999999999999999999999999")).equals("abc"), "arbitrarily large valid n must leave short text unchanged");
        check(Solution.runPipeline("abcdef", List.of("take:0002")).equals("ab"), "leading-zero decimal n must be accepted");
        check(Solution.runPipeline("A\uD83D\uDE00B", List.of("take:2")).equals("A\uD83D"), "take must count UTF-16 code units");
        check(Solution.runPipeline("Straße", List.of("upper", "lower")).equals("strasse"), "case conversion must be applied in order");
        check(Solution.runPipeline("ab\uD83D\uDE00", List.of("reverse")).equals("\uD83D\uDE00ba"), "reverse command failed");

        expectIAE(() -> Solution.runPipeline(null, List.of()));
        expectIAE(() -> Solution.runPipeline("x", null));
        expectIAE(() -> Solution.runPipeline("x", Arrays.asList("trim", null)));
        for (String invalid : List.of("", " trim", "trim ", "Upper", "take", "take:", "take:-1", "take:+1", "take: 1", "take:1 ", "take:1.0", "take:١", "take:12x", "unknown")) {
            expectIAE(() -> Solution.runPipeline("value", List.of(invalid)));
        }
    }
}

