package solution

import (
	"strings"
	"testing"
	"unicode/utf8"
)

func TestAccountStoreRegistrationNormalizationAndIDs(t *testing.T) {
	s, err := NewAccountStore([]byte("secret"))
	if err != nil {
		t.Fatalf("NewAccountStore: %v", err)
	}

	if _, err := s.Register("bad", "bad@example.com", "short"); err == nil {
		t.Fatal("short password accepted")
	}
	first, err := s.Register("\u2003Alice Smith\u00a0", "  ALICE@Example.COM\n", "12345678")
	if err != nil {
		t.Fatalf("Register first: %v", err)
	}
	if first != (PublicAccount{ID: "u1", Name: "Alice Smith", Email: "alice@example.com"}) {
		t.Fatalf("unexpected first account: %#v", first)
	}

	if _, err := s.Register("Duplicate", "alice@example.COM", "abcdefgh"); err == nil {
		t.Fatal("duplicate normalized email accepted")
	}
	second, err := s.Register("Alice Smith", "second@example.com", "éééé")
	if err != nil {
		t.Fatalf("eight-byte password rejected: %v (bytes=%d)", err, len("éééé"))
	}
	if second.ID != "u2" {
		t.Fatalf("failed registrations consumed an ID: got %q", second.ID)
	}

	for _, tc := range []struct{ name, email string }{
		{"\u2003\t", "third@example.com"},
		{"Third", " \n\u00a0"},
	} {
		if _, err := s.Register(tc.name, tc.email, "abcdefgh"); err == nil {
			t.Fatalf("invalid registration accepted: name=%q email=%q", tc.name, tc.email)
		}
	}
	third, err := s.Register("Third", "third@example.com", "abcdefgh")
	if err != nil {
		t.Fatalf("Register after invalid calls: %v", err)
	}
	if third.ID != "u3" {
		t.Fatalf("invalid calls consumed an ID: got %q", third.ID)
	}
}

func TestAccountStoreAuthenticationVerificationAndSecretCopy(t *testing.T) {
	secret := []byte("original-secret")
	s, err := NewAccountStore(secret)
	if err != nil {
		t.Fatal(err)
	}
	secret[0] = 'X'

	want, err := s.Register("Zoë", "User@Example.COM", "password")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.Authenticate("missing@example.com", "password"); err == nil {
		t.Fatal("missing user authenticated")
	}
	if _, err := s.Authenticate("user@example.com", "wrong-password"); err == nil {
		t.Fatal("wrong password authenticated")
	}

	token1, err := s.Authenticate(" \u2003USER@example.com\n", "password")
	if err != nil {
		t.Fatalf("Authenticate normalized email: %v", err)
	}
	token2, err := s.Authenticate("user@example.com", "password")
	if err != nil {
		t.Fatal(err)
	}
	if token1 == "" || token1 != token2 {
		t.Fatalf("tokens are empty or nondeterministic: %q %q", token1, token2)
	}
	if strings.Contains(token1, "=") || !utf8.ValidString(token1) {
		t.Fatalf("token is not unpadded textual base64url form: %q", token1)
	}
	for _, r := range token1 {
		if !(r >= 'a' && r <= 'z') && !(r >= 'A' && r <= 'Z') && !(r >= '0' && r <= '9') && r != '-' && r != '_' && r != '.' {
			t.Fatalf("token contains non-URL-safe character %q", r)
		}
	}

	got, err := s.Verify(token1)
	if err != nil {
		t.Fatalf("Verify canonical token: %v", err)
	}
	if got != want {
		t.Fatalf("Verify returned %#v, want %#v", got, want)
	}

	altered := []byte(token1)
	if altered[len(altered)-1] == 'A' {
		altered[len(altered)-1] = 'B'
	} else {
		altered[len(altered)-1] = 'A'
	}
	embeddedLF := token1[:len(token1)-1] + "\n" + token1[len(token1)-1:]
	embeddedCR := token1[:len(token1)-1] + "\r" + token1[len(token1)-1:]
	for _, bad := range []string{
		"",
		"not a token",
		string(altered),
		token1 + "\n",
		token1 + "\r",
		embeddedLF,
		embeddedCR,
	} {
		if _, err := s.Verify(bad); err == nil {
			t.Fatalf("invalid token accepted: %q", bad)
		}
	}

	other, err := NewAccountStore([]byte("different-secret"))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := other.Verify(token1); err == nil {
		t.Fatal("token verified in a store with another secret")
	}
}

func TestAccountStoreFindByNameOrderAndIsolation(t *testing.T) {
	s, _ := NewAccountStore([]byte("secret"))
	a, _ := s.Register(" Same ", "a@example.com", "12345678")
	b, _ := s.Register("Same", "b@example.com", "12345678")
	_, _ = s.Register("same", "c@example.com", "12345678")

	got := s.FindByName("Same")
	if len(got) != 2 || got[0] != a || got[1] != b {
		t.Fatalf("unexpected name results: %#v", got)
	}
	got[0].Name = "corrupted"
	got[1] = PublicAccount{}
	again := s.FindByName("Same")
	if len(again) != 2 || again[0] != a || again[1] != b {
		t.Fatalf("returned data aliased store state: %#v", again)
	}
	if results := s.FindByName("missing"); len(results) != 0 {
		t.Fatalf("missing name returned %#v", results)
	}
}

func TestNewAccountStoreRejectsEmptySecret(t *testing.T) {
	for _, secret := range [][]byte{nil, {}} {
		if _, err := NewAccountStore(secret); err == nil {
			t.Fatal("empty secret accepted")
		}
	}
}

