		return PublicAccount{}, errors.New("invalid registration")
	}
	if _, exists := s.byEmail[email]; exists {
		return PublicAccount{}, errors.New("duplicate email")
	}
	id := "u" + strconv.FormatUint(s.next, 10)
	public := PublicAccount{ID: id, Name: name, Email: email}
	s.byID[id] = storedAccount{public: public, digest: passwordDigest(id, password)}
	s.byEmail[email] = id
	s.next++
	return public, nil
}

func (s *AccountStore) Authenticate(email, password string) (string, error) {
	id, exists := s.byEmail[normalizeEmail(email)]
	if !exists {
		return "", errors.New("invalid credentials")
	}
	account := s.byID[id]
	if account.digest != passwordDigest(id, password) {
		return "", errors.New("invalid credentials")
	}
	payload := base64.RawURLEncoding.EncodeToString([]byte(id))
	mac := hmac.New(sha256.New, s.secret)
	_, _ = mac.Write([]byte(payload))
	return payload + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
}

func (s *AccountStore) Verify(token string) (PublicAccount, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return PublicAccount{}, errors.New("malformed token")
	}
	idBytes, e1 := base64.RawURLEncoding.DecodeString(parts[0])
	sig, e2 := base64.RawURLEncoding.DecodeString(parts[1])
	if e1 != nil || e2 != nil || len(idBytes) == 0 ||
		base64.RawURLEncoding.EncodeToString(idBytes) != parts[0] ||
		base64.RawURLEncoding.EncodeToString(sig) != parts[1] {
		return PublicAccount{}, errors.New("malformed token")
	}
	mac := hmac.New(sha256.New, s.secret)
	_, _ = mac.Write([]byte(parts[0]))
	if !hmac.Equal(sig, mac.Sum(nil)) {
		return PublicAccount{}, errors.New("invalid token")
	}
	account, exists := s.byID[string(idBytes)]
	if !exists {
		return PublicAccount{}, errors.New("unknown account")
	}
	return account.public, nil
}

func (s *AccountStore) FindByName(name string) []PublicAccount {
	name = strings.TrimSpace(name)
	out := make([]PublicAccount, 0)
	for _, account := range s.byID {
		if account.public.Name == name {
			out = append(out, account.public)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

