	mac := hmac.New(sha256.New, s.key)
	_, _ = mac.Write([]byte(payloadPart))
	signaturePart := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return payloadPart + "." + signaturePart, nil
}

func (s *PassService) Verify(token string, at int64) (PassClaims, error) {
	if s == nil || len(s.key) == 0 {
		return PassClaims{}, fmt.Errorf("service is not initialized")
	}
	if at < 0 {
		return PassClaims{}, fmt.Errorf("verification time must not be negative")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return PassClaims{}, fmt.Errorf("malformed token")
	}
	payload, payloadErr := base64.RawURLEncoding.DecodeString(parts[0])
	signature, signatureErr := base64.RawURLEncoding.DecodeString(parts[1])
	if payloadErr != nil || signatureErr != nil ||
		base64.RawURLEncoding.EncodeToString(payload) != parts[0] ||
		base64.RawURLEncoding.EncodeToString(signature) != parts[1] {
		return PassClaims{}, fmt.Errorf("malformed token encoding")
	}
	mac := hmac.New(sha256.New, s.key)
	_, _ = mac.Write([]byte(parts[0]))
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return PassClaims{}, fmt.Errorf("invalid signature")
	}
	dec := json.NewDecoder(bytes.NewReader(payload))
	dec.DisallowUnknownFields()
	var claims PassClaims
	if err := dec.Decode(&claims); err != nil {
		return PassClaims{}, fmt.Errorf("decode claims: %w", err)
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		return PassClaims{}, fmt.Errorf("trailing claims data")
	}
	if err := validatePassClaims(claims); err != nil {
		return PassClaims{}, err
	}
	if at >= claims.ExpiresAt {
		return PassClaims{}, fmt.Errorf("token expired")
