package solution

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"strings"
	"testing"
)

func makePassToken(payload []byte, key string) string {
	part := base64.RawURLEncoding.EncodeToString(payload)
	mac := hmac.New(sha256.New, []byte(key))
	_, _ = mac.Write([]byte(part))
	return part + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func TestPassServiceIssueFormatAndDeterminism(t *testing.T) {
	service, err := NewPassService("key")
	if err != nil {
		t.Fatal(err)
	}
	claims := PassClaims{Subject: "subject", DisplayName: "Display", ExpiresAt: 99}
	got, err := service.Issue(claims)
	if err != nil {
		t.Fatalf("Issue: %v", err)
	}
	payload, err := json.Marshal(struct {
		Subject     string `json:"sub"`
		DisplayName string `json:"name"`
		ExpiresAt   int64  `json:"exp"`
	}{claims.Subject, claims.DisplayName, claims.ExpiresAt})
	if err != nil {
		t.Fatal(err)
	}
	want := makePassToken(payload, "key")
	if got != want {
		t.Fatalf("token = %q, want %q", got, want)
	}
	again, err := service.Issue(claims)
	if err != nil || again != got {
		t.Fatalf("Issue is nondeterministic: %q, %v", again, err)
	}
	if strings.Contains(got, "=") {
		t.Fatalf("token contains base64 padding: %q", got)
	}
	verified, err := service.Verify(got, 0)
	if err != nil || verified != claims {
		t.Fatalf("Verify canonical token = %#v, %v; want %#v", verified, err, claims)
	}
}

func TestPassServiceValidationAndExpirationBoundary(t *testing.T) {
	if _, err := NewPassService(""); err == nil {
		t.Fatal("empty key accepted")
	}
	service, _ := NewPassService("key")
	for _, claims := range []PassClaims{
		{Subject: "", ExpiresAt: 1},
		{Subject: "s", ExpiresAt: 0},
		{Subject: "s", ExpiresAt: -1},
	} {
		if _, err := service.Issue(claims); err == nil {
			t.Fatalf("invalid claims accepted: %#v", claims)
		}
	}
	token, err := service.Issue(PassClaims{Subject: "s", ExpiresAt: 10})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := service.Verify(token, -1); err == nil {
		t.Fatal("negative verification time accepted")
	}
	if _, err := service.Verify(token, 9); err != nil {
		t.Fatalf("token expired too early: %v", err)
	}
	if _, err := service.Verify(token, 10); err == nil {
		t.Fatal("token valid at exact expiration")
	}
	if _, err := service.Verify(token, 11); err == nil {
		t.Fatal("expired token accepted")
	}
}

func TestPassServiceRejectsMalformedAndAlteredTokens(t *testing.T) {
	service, _ := NewPassService("key")
	valid, _ := service.Issue(PassClaims{Subject: "s", DisplayName: "", ExpiresAt: 20})
	parts := strings.Split(valid, ".")
	if len(parts) != 2 {
		t.Fatalf("issued token has %d segments, want 2", len(parts))
	}
	alteredSignature := parts[1]
	if alteredSignature[0] == 'A' {
		alteredSignature = "B" + alteredSignature[1:]
	} else {
		alteredSignature = "A" + alteredSignature[1:]
	}

	badTokens := []string{
		"",
		"onepart",
		"a.b.c",
		"*." + parts[1],
		parts[0] + ".*",
		parts[0] + "." + alteredSignature,
		valid + "\n",
		valid + "\r",
		parts[0][:1] + "\n" + parts[0][1:] + "." + parts[1],
		parts[0][:1] + "\r" + parts[0][1:] + "." + parts[1],
		parts[0] + "." + parts[1][:1] + "\n" + parts[1][1:],
		parts[0] + "." + parts[1][:1] + "\r" + parts[1][1:],
		makePassToken([]byte("{"), "key"),
		makePassToken([]byte(`{"sub":"s","name":"","exp":20} {}`), "key"),
		makePassToken([]byte(`{"sub":"","name":"","exp":20}`), "key"),
		makePassToken([]byte(`{"sub":"s","name":"","exp":0}`), "key"),
	}
	for _, token := range badTokens {
		if _, err := service.Verify(token, 0); err == nil {
			t.Fatalf("invalid token accepted: %q", token)
		}
	}
}

