package solution

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"math"
	"strings"
	"testing"
)

func buildSessionCredential(payload []byte, secret []byte) string {
	part := base64.RawURLEncoding.EncodeToString(payload)
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write([]byte(part))
	return part + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func TestGenerateSessionCredentialFormatAndInputs(t *testing.T) {
	secret := []byte("secret")
	original := append([]byte(nil), secret...)
	got, err := GenerateSessionCredential("user", "contact@example.com", secret, 7)
	if err != nil {
		t.Fatalf("GenerateSessionCredential: %v", err)
	}
	if string(secret) != string(original) {
		t.Fatal("generation mutated secret")
	}
	claims := SessionClaims{Subject: "user", Contact: "contact@example.com", IssuedAt: 7, ExpiresAt: 86407}
	payload, _ := json.Marshal(claims)
	want := buildSessionCredential(payload, secret)
	if got != want {
		t.Fatalf("credential = %q, want %q", got, want)
	}
	if strings.Contains(got, "=") {
		t.Fatalf("credential contains padding: %q", got)
	}

	gotClaims, err := VerifySessionCredential(got, secret, 7)
	if err != nil || gotClaims != claims {
		t.Fatalf("VerifySessionCredential canonical token = %#v, %v; want %#v", gotClaims, err, claims)
	}
}

func TestGenerateSessionCredentialValidationAndOverflow(t *testing.T) {
	tests := []struct {
		subject string
		contact string
		secret  []byte
		issued  int64
	}{
		{"", "c", []byte("s"), 0},
		{"s", "", []byte("s"), 0},
		{"s", "c", nil, 0},
		{"s", "c", []byte{}, 0},
		{"s", "c", []byte("s"), -1},
		{"s", "c", []byte("s"), math.MaxInt64 - 86399},
	}
	for _, tc := range tests {
		if _, err := GenerateSessionCredential(tc.subject, tc.contact, tc.secret, tc.issued); err == nil {
			t.Fatalf("invalid generation accepted: %+v", tc)
		}
	}
	if _, err := GenerateSessionCredential(" ", " ", []byte("s"), math.MaxInt64-86400); err != nil {
		t.Fatalf("valid boundary generation rejected: %v", err)
	}
}

func TestVerifySessionCredentialTimeBoundaries(t *testing.T) {
	token, _ := GenerateSessionCredential("s", "c", []byte("key"), 10)
	for _, now := range []int64{10, 86409} {
		if _, err := VerifySessionCredential(token, []byte("key"), now); err != nil {
			t.Fatalf("valid time %d rejected: %v", now, err)
		}
	}
	for _, now := range []int64{-1, 9, 86410, 86411} {
		if _, err := VerifySessionCredential(token, []byte("key"), now); err == nil {
			t.Fatalf("invalid time %d accepted", now)
		}
	}
	if _, err := VerifySessionCredential(token, nil, 10); err == nil {
		t.Fatal("empty verification secret accepted")
	}
}

func TestVerifySessionCredentialRejectsMalformedSignedPayloads(t *testing.T) {
	secret := []byte("key")
	valid, _ := GenerateSessionCredential("s", "c", secret, 0)
	parts := strings.Split(valid, ".")
	if len(parts) != 2 {
		t.Fatalf("issued credential has %d segments, want 2", len(parts))
	}
	changed := parts[1]
	if changed[0] == 'A' {
		changed = "B" + changed[1:]
	} else {
		changed = "A" + changed[1:]
	}

	bad := []string{
		"",
		"single",
		"a.b.c",
		"*." + parts[1],
		parts[0] + ".*",
		parts[0] + "." + changed,
		valid + "\n",
		valid + "\r",
		parts[0] + "." + parts[1][:1] + "\n" + parts[1][1:],
		buildSessionCredential([]byte("{"), secret),
		buildSessionCredential([]byte(`{"sub":"s","contact":"c","iat":0,"exp":86400} {}`), secret),
		buildSessionCredential([]byte(`{"sub":"s","contact":"c","iat":0,"exp":86400,"extra":1}`), secret),
		buildSessionCredential([]byte(`{"sub":"","contact":"c","iat":0,"exp":86400}`), secret),
		buildSessionCredential([]byte(`{"sub":"s","contact":"","iat":0,"exp":86400}`), secret),
		buildSessionCredential([]byte(`{"sub":"s","contact":"c","iat":-1,"exp":86399}`), secret),
		buildSessionCredential([]byte(`{"sub":"s","contact":"c","iat":0,"exp":86401}`), secret),
	}
	for _, token := range bad {
		if _, err := VerifySessionCredential(token, secret, 0); err == nil {
			t.Fatalf("invalid credential accepted: %q", token)
		}
	}
}

func TestSessionCredentialDoesNotRetainSecret(t *testing.T) {
	secret := []byte("mutable")
