package solution

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"strings"
	"testing"
)

func makeMintedToken(payload []byte, secret []byte) string {
	payloadPart := base64.RawURLEncoding.EncodeToString(payload)
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write(payload)
	return payloadPart + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func TestMintSessionExactFormatAndRoundTrip(t *testing.T) {
	secret := []byte("secret")
	before := append([]byte(nil), secret...)
	claims := SessionClaims{AccountID: "acct-1", Scope: "read write", IssuedAt: 5, ExpiresAt: 10}
	got, err := MintSession(secret, claims)
	if err != nil {
		t.Fatalf("MintSession: %v", err)
	}
	if string(secret) != string(before) {
		t.Fatal("MintSession mutated secret")
	}
	payload, _ := json.Marshal(claims)
	want := makeMintedToken(payload, secret)
	if got != want {
		t.Fatalf("token = %q, want %q", got, want)
	}
	if strings.Contains(got, "=") {
		t.Fatalf("token contains padding: %q", got)
	}

	verified, err := VerifySession(secret, got, 0)
	if err != nil || verified != claims {
		t.Fatalf("VerifySession canonical token = %#v, %v; want %#v", verified, err, claims)
	}
}

func TestMintSessionValidation(t *testing.T) {
	valid := SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 0, ExpiresAt: 1}
	tests := []struct {
		secret []byte
		claims SessionClaims
	}{
		{nil, valid},
		{[]byte{}, valid},
		{[]byte("k"), SessionClaims{Scope: "s", ExpiresAt: 1}},
		{[]byte("k"), SessionClaims{AccountID: "a", ExpiresAt: 1}},
		{[]byte("k"), SessionClaims{AccountID: "a", Scope: "s", IssuedAt: -1, ExpiresAt: 1}},
		{[]byte("k"), SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 0, ExpiresAt: -1}},
		{[]byte("k"), SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 1, ExpiresAt: 1}},
		{[]byte("k"), SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 2, ExpiresAt: 1}},
	}
	for _, tc := range tests {
		if _, err := MintSession(tc.secret, tc.claims); err == nil {
			t.Fatalf("invalid mint accepted: %#v", tc)
		}
	}
}

func TestVerifySessionTimeRules(t *testing.T) {
	secret := []byte("key")
	token, _ := MintSession(secret, SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 100, ExpiresAt: 200})
	for _, now := range []int64{0, 99, 100, 199} {
		if _, err := VerifySession(secret, token, now); err != nil {
			t.Fatalf("valid verification time %d rejected: %v", now, err)
		}
	}
	for _, now := range []int64{-1, 200, 201} {
		if _, err := VerifySession(secret, token, now); err == nil {
			t.Fatalf("invalid verification time %d accepted", now)
		}
	}
	if _, err := VerifySession(nil, token, 100); err == nil {
		t.Fatal("empty verification secret accepted")
	}
}

func TestVerifySessionRejectsMalformedAndNonCanonicalTokens(t *testing.T) {
	secret := []byte("key")
	valid, _ := MintSession(secret, SessionClaims{AccountID: "a", Scope: "s", IssuedAt: 0, ExpiresAt: 10})
	parts := strings.Split(valid, ".")
	if len(parts) != 2 {
		t.Fatalf("minted token has %d segments, want 2", len(parts))
	}
	changed := parts[1]
	if changed[0] == 'A' {
		changed = "B" + changed[1:]
	} else {
		changed = "A" + changed[1:]
	}

	bad := []string{
		"",
		"single",
		"a.b.c",
		"*." + parts[1],
		parts[0] + ".*",
		parts[0] + "." + changed,
		valid + "\n",
		valid + "\r",
		parts[0][:1] + "\n" + parts[0][1:] + "." + parts[1],
		parts[0][:1] + "\r" + parts[0][1:] + "." + parts[1],
		parts[0] + "." + parts[1][:1] + "\n" + parts[1][1:],
		parts[0] + "." + parts[1][:1] + "\r" + parts[1][1:],
		makeMintedToken([]byte("{"), secret),
		makeMintedToken([]byte(`{"account_id":"a","scope":"s","issued_at":0,"expires_at":10} {}`), secret),
		makeMintedToken([]byte(`{"account_id":"a","scope":"s","issued_at":0,"expires_at":10,"unknown":true}`), secret),
		makeMintedToken([]byte(`{"account_id":"","scope":"s","issued_at":0,"expires_at":10}`), secret),
		makeMintedToken([]byte(`{"account_id":"a","scope":"","issued_at":0,"expires_at":10}`), secret),
		makeMintedToken([]byte(`{"account_id":"a","scope":"s","issued_at":-1,"expires_at":10}`), secret),
		makeMintedToken([]byte(`{"account_id":"a","scope":"s","issued_at":10,"expires_at":10}`), secret),
	}
	for _, token := range bad {
		if _, err := VerifySession(secret, token, 0); err == nil {
			t.Fatalf("invalid token accepted: %q", token)
		}
	}
}

func TestSessionFunctionsDoNotRetainSecret(t *testing.T) {
	secret := []byte("mutable")
	token, err := MintSession(secret, SessionClaims{AccountID: "a", Scope: "s", ExpiresAt: 1})
	if err != nil {
		t.Fatal(err)
	}
	secret[0] = 'X'
	if _, err := VerifySession([]byte("mutable"), token, 0); err != nil {
		t.Fatalf("token changed after caller mutated secret: %v", err)
	}
}

