package solution

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"strings"
)

type DeviceConfig struct {
	Label string `json:"label"`
	Level uint8  `json:"level"`
	token string
}

func NewDeviceConfig(label string, level uint8, token string) DeviceConfig {
	return DeviceConfig{Label: label, Level: level, token: token}
}

func (c DeviceConfig) Token() string {
	return c.token
}

func validConfig(c DeviceConfig) bool {
	return strings.TrimSpace(c.Label) != "" && c.Level <= 10
}

func EncodeDeviceConfig(c DeviceConfig) ([]byte, error) {
	if !validConfig(c) {
		return nil, errors.New("invalid device configuration")
	}
	type wireConfig struct {
		Label string `json:"label"`
		Level uint8  `json:"level"`
	}
	return json.Marshal(wireConfig{Label: c.Label, Level: c.Level})
}

func DecodeDeviceConfig(data []byte) (DeviceConfig, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	first, err := dec.Token()
	if err != nil {
		return DeviceConfig{}, err
	}
	if first != json.Delim('{') {
		return DeviceConfig{}, errors.New("configuration must be an object")
	}

	seen := make(map[string]bool, 2)
	var label *string
	var level *uint8
	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return DeviceConfig{}, err
		}
		key, ok := keyToken.(string)
		if !ok || (key != "label" && key != "level") {
			return DeviceConfig{}, errors.New("unknown field")
		}
		if seen[key] {
			return DeviceConfig{}, errors.New("duplicate field")
		}
		seen[key] = true
		switch key {
		case "label":
			if err := dec.Decode(&label); err != nil || label == nil {
				return DeviceConfig{}, errors.New("invalid label")
			}
		case "level":
			if err := dec.Decode(&level); err != nil || level == nil {
				return DeviceConfig{}, errors.New("invalid level")
			}
		}
	}
	end, err := dec.Token()
	if err != nil || end != json.Delim('}') {
		return DeviceConfig{}, errors.New("malformed configuration")
	}
	if err := requireEOF(dec); err != nil {
		return DeviceConfig{}, err
	}
	if label == nil || level == nil {
		return DeviceConfig{}, errors.New("missing required field")
	}
	result := DeviceConfig{Label: *label, Level: *level}
	if !validConfig(result) {
		return DeviceConfig{}, errors.New("invalid device configuration")
	}
	return result, nil
}

func DecodeJSONObject(data []byte) (map[string]interface{}, error) {
	var value interface{}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(&value); err != nil {
		return nil, err
	}
	if err := requireEOF(dec); err != nil {
		return nil, err
	}
	object, ok := value.(map[string]interface{})
	if !ok {
		return nil, errors.New("top-level value is not an object")
	}
	return object, nil
}

func requireEOF(dec *json.Decoder) error {
	var extra interface{}
	err := dec.Decode(&extra)
	if err == io.EOF {
		return nil
	}
	if err == nil {
		return errors.New("trailing JSON value")
	}
