package solution

import (
	"bytes"
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

func TestDeviceConfigConstructionEncodingAndPrivacy(t *testing.T) {
	config := NewDeviceConfig("sensor", 10, "private-token")
	if config.Label != "sensor" || config.Level != 10 || config.Token() != "private-token" {
		t.Fatalf("unexpected constructed config: label=%q level=%d token=%q", config.Label, config.Level, config.Token())
	}
	encoded, err := EncodeDeviceConfig(config)
	if err != nil {
		t.Fatalf("EncodeDeviceConfig: %v", err)
	}
	if bytes.Contains(encoded, []byte("private-token")) || bytes.Contains(encoded, []byte("token")) {
		t.Fatalf("private token leaked into JSON: %s", encoded)
	}
	var object map[string]interface{}
	decoder := json.NewDecoder(bytes.NewReader(encoded))
	decoder.UseNumber()
	if err := decoder.Decode(&object); err != nil {
		t.Fatal(err)
	}
	want := map[string]interface{}{"label": "sensor", "level": json.Number("10")}
	if !reflect.DeepEqual(object, want) {
		t.Fatalf("encoded object = %#v, want %#v", object, want)
	}

	decoded, err := DecodeDeviceConfig(encoded)
	if err != nil {
		t.Fatalf("DecodeDeviceConfig: %v", err)
	}
	if decoded.Label != "sensor" || decoded.Level != 10 || decoded.Token() != "" {
		t.Fatalf("unexpected decoded config: label=%q level=%d token=%q", decoded.Label, decoded.Level, decoded.Token())
	}
}

func TestDeviceConfigValidationBoundaries(t *testing.T) {
	for _, level := range []uint8{0, 10} {
		config := NewDeviceConfig("x", level, "secret")
		if _, err := EncodeDeviceConfig(config); err != nil {
			t.Fatalf("valid level %d rejected by encoder: %v", level, err)
		}
		input := []byte(`{"label":"x","level":0}`)
		if level == 10 {
			input = []byte(`{"label":"x","level":10}`)
		}
		if _, err := DecodeDeviceConfig(input); err != nil {
			t.Fatalf("valid level %d rejected by decoder: %v", level, err)
		}
	}
	for _, config := range []DeviceConfig{
		NewDeviceConfig("", 0, ""),
		NewDeviceConfig(" \t\n\u2003", 0, ""),
		NewDeviceConfig("x", 11, ""),
		NewDeviceConfig("x", 255, ""),
	} {
		if _, err := EncodeDeviceConfig(config); err == nil {
			t.Fatalf("invalid config encoded: %#v", config)
		}
	}
}

func TestDecodeDeviceConfigExactDecodedKeys(t *testing.T) {
	for _, input := range [][]byte{
		[]byte(`{"label":"x","level":1}`),
		[]byte(`{"la\u0062el":"x","lev\u0065l":1}`),
	} {
		got, err := DecodeDeviceConfig(input)
		if err != nil {
			t.Fatalf("valid lowercase keys rejected for %q: %v", input, err)
		}
		if got.Label != "x" || got.Level != 1 || got.Token() != "" {
			t.Fatalf("decoded config = %#v", got)
		}
	}

	for _, input := range [][]byte{
		[]byte(`{"Label":"x","level":1}`),
		[]byte(`{"label":"x","Level":1}`),
		[]byte(`{"LABEL":"x","LEVEL":1}`),
	} {
		if _, err := DecodeDeviceConfig(input); err == nil {
			t.Fatalf("noncanonical key casing accepted: %q", input)
		}
	}
}

func TestDecodeDeviceConfigRejectsMalformedAmbiguousAndWrongShapes(t *testing.T) {
	bad := [][]byte{
		nil,
		{},
		[]byte("   \n\t"),
		[]byte("null"),
		[]byte("[]"),
		[]byte(`{"label":"x"}`),
		[]byte(`{"level":1}`),
		[]byte(`{"label":"x","level":1,"extra":true}`),
		[]byte(`{"label":"x","label":"y","level":1}`),
		[]byte(`{"label":"x","la\u0062el":"y","level":1}`),
		[]byte(`{"label":"x","level":1,"level":2}`),
		[]byte(`{"label":"x","level":1,"lev\u0065l":2}`),
		[]byte(`{"label":1,"level":1}`),
		[]byte(`{"label":null,"level":1}`),
		[]byte(`{"label":"x","level":"1"}`),
		[]byte(`{"label":"x","level":null}`),
		[]byte(`{"label":"x","level":-1}`),
		[]byte(`{"label":"x","level":11}`),
		[]byte(`{"label":"   ","level":1}`),
		[]byte(`{"label":"x","level":1.5}`),
		[]byte(`{"label":"x","level":1} trailing`),
		[]byte(`{"label":"x","level":1} {}`),
		[]byte(`{"label":"x","level":1`),
	}
	for _, input := range bad {
		before := append([]byte(nil), input...)
		if _, err := DecodeDeviceConfig(input); err == nil {
			t.Fatalf("invalid configuration accepted: %q", input)
		}
		if !bytes.Equal(input, before) {
			t.Fatalf("decoder mutated input: before=%q after=%q", before, input)
		}
	}
}

func TestDecodeDeviceConfigAllowsWhitespaceAroundCompleteDocument(t *testing.T) {
	input := []byte(" \n\t{\"label\":\" device \u2003\",\"level\":0}\r\n ")
	before := append([]byte(nil), input...)
	got, err := DecodeDeviceConfig(input)
	if err != nil {
		t.Fatalf("valid whitespace rejected: %v", err)
	}
	if got.Label != " device \u2003" || got.Level != 0 || got.Token() != "" {
		t.Fatalf("decoded config = %#v", got)
	}
	if !bytes.Equal(input, before) {
		t.Fatal("DecodeDeviceConfig mutated input")
	}
}

func TestDecodeJSONObjectTypesDuplicatesAndTopLevelValidation(t *testing.T) {
	input := []byte(`{"n":9007199254740993,"dup":1,"dup":2,"nested":{"v":3},"array":[4,true,null]}`)
	before := append([]byte(nil), input...)
	got, err := DecodeJSONObject(input)
	if err != nil {
		t.Fatalf("DecodeJSONObject: %v", err)
	}
	if !bytes.Equal(input, before) {
		t.Fatal("DecodeJSONObject mutated input")
	}
	if n, ok := got["n"].(json.Number); !ok || n.String() != "9007199254740993" {
		t.Fatalf("number was not preserved as json.Number: %#v", got["n"])
	}
	if dup, ok := got["dup"].(json.Number); !ok || dup.String() != "2" {
		t.Fatalf("duplicate key did not use last value: %#v", got["dup"])
	}
	nested, ok := got["nested"].(map[string]interface{})
	if !ok {
		t.Fatalf("nested object has type %T", got["nested"])
	}
	if v, ok := nested["v"].(json.Number); !ok || v.String() != "3" {
		t.Fatalf("nested number = %#v", nested["v"])
	}
	array, ok := got["array"].([]interface{})
	if !ok || len(array) != 3 {
		t.Fatalf("array = %#v", got["array"])
	}
	if v, ok := array[0].(json.Number); !ok || v.String() != "4" {
		t.Fatalf("array number = %#v", array[0])
	}

	empty, err := DecodeJSONObject([]byte(" \n{}\t"))
	if err != nil || len(empty) != 0 || empty == nil {
		t.Fatalf("empty object = %#v, %v", empty, err)
	}
	for _, bad := range [][]byte{
		nil, {}, []byte("  "), []byte("null"), []byte("[]"), []byte(`"x"`),
		[]byte("1"), []byte("true"), []byte("{"), []byte(`{} x`), []byte(`{} {}`),
	} {
		if _, err := DecodeJSONObject(bad); err == nil {
			t.Fatalf("invalid top-level JSON accepted: %q", bad)
		}
	}
}

func TestDecodeJSONObjectReturnsFreshNestedData(t *testing.T) {
	input := []byte(`{"text":"abcdef","nested":{"x":1},"list":[{"y":2}]}`)
	first, err := DecodeJSONObject(input)
	if err != nil {
		t.Fatal(err)
	}
	for i := range input {
		input[i] = 'x'
	}
	if first["text"] != "abcdef" {
		t.Fatalf("decoded string aliases input bytes: %#v", first["text"])
	}
	first["nested"].(map[string]interface{})["x"] = json.Number("99")
	first["list"].([]interface{})[0].(map[string]interface{})["y"] = json.Number("99")

	second, err := DecodeJSONObject([]byte(`{"text":"abcdef","nested":{"x":1},"list":[{"y":2}]}`))
	if err != nil {
		t.Fatal(err)
	}
	if second["nested"].(map[string]interface{})["x"].(json.Number).String() != "1" ||
		second["list"].([]interface{})[0].(map[string]interface{})["y"].(json.Number).String() != "2" {
		t.Fatalf("separate decode results alias each other: %#v", second)
	}
	if strings.Contains(second["text"].(string), "x") {
		t.Fatalf("unexpected decoded string: %q", second["text"])
	}
}

