import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("expected IllegalArgumentException");
    }

    private static void expectISE(Runnable action) {
        try { action.run(); } catch (IllegalStateException expected) { return; }
        throw new AssertionError("expected IllegalStateException");
    }

    private static void expectUOE(Runnable action) {
        try { action.run(); } catch (UnsupportedOperationException expected) { return; }
        throw new AssertionError("expected UnsupportedOperationException");
    }

    public static void main(String[] args) {
        expectIAE(() -> Solution.configure(0, 1));
        expectIAE(() -> Solution.configure(1, 0));
        expectISE(() -> Solution.add(new Solution.Command("x", 1)));
        expectISE(() -> Solution.addAll(List.of()));
        expectISE(Solution::flush);
        expectISE(Solution::close);

        Solution.configure(5, 2);
        Solution.Command a = new Solution.Command("a", 1);
        Solution.Command b = new Solution.Command("b", 2);
        check(a.getText().equals("a") && a.getWeight() == 1, "command getters failed");
        Solution.add(a);
        check(Solution.committed().isEmpty(), "weight below threshold must remain buffered");
        Solution.add(b);
        List<Solution.Command> committed = Solution.committed();
        check(committed.size() == 2 && committed.get(0) == a && committed.get(1) == b, "threshold batch order is wrong");
        expectUOE(() -> committed.clear());

        Solution.Command c = new Solution.Command("c", 1);
        Solution.add(c);
        List<Solution.Command> flushed = Solution.flush();
        check(flushed.size() == 1 && flushed.get(0) == c, "flush must return current batch");
        expectUOE(() -> flushed.add(a));
        check(Solution.flush().isEmpty(), "empty flush must return empty list");
        expectUOE(() -> Solution.flush().add(a));

        ArrayList<Solution.Command> input = new ArrayList<>();
        Solution.Command d = new Solution.Command("d", 1);
        Solution.Command e = new Solution.Command("e", 2);
        input.add(d);
        input.add(e);
        Solution.addAll(input);
        input.clear();
        List<Solution.Command> afterAddAll = Solution.committed();
        check(afterAddAll.size() == 5, "all committed commands must be retained");
        check(afterAddAll.get(3) == d && afterAddAll.get(4) == e, "addAll must preserve order and copy input");
        check(committed.size() == 2, "committed result must be a snapshot");

        expectIAE(() -> new Solution.Command(null, 1));
        expectIAE(() -> new Solution.Command("", 1));
        expectIAE(() -> Solution.add(null));
        expectIAE(() -> Solution.add(new Solution.Command("zero", 0)));
        expectIAE(() -> Solution.add(new Solution.Command("heavy", 6)));
        expectIAE(() -> Solution.addAll(null));
        expectIAE(() -> Solution.addAll(Arrays.asList(new Solution.Command("ok", 1), null)));
        check(Solution.committed().size() == 5, "invalid addAll must not commit a partial batch");
        check(Solution.flush().isEmpty(), "invalid addAll must not leave a partial buffer");

        Solution.Command pending = new Solution.Command("pending", 1);
        Solution.add(pending);
        Solution.close();
        check(Solution.isClosed(), "close must mark sink closed");
        List<Solution.Command> closedCommitted = Solution.committed();
        check(closedCommitted.get(closedCommitted.size() - 1) == pending, "close must flush pending commands");
        expectISE(() -> Solution.add(a));
        expectISE(() -> Solution.addAll(List.of(a)));
        expectISE(Solution::flush);
        expectISE(Solution::close);

        Solution.configure(2, 1);
        check(!Solution.isClosed(), "reconfigure must open sink");
        check(Solution.committed().isEmpty(), "reconfigure must clear committed state");
        Solution.Command fresh = new Solution.Command("fresh", 1);
        Solution.add(fresh);
        check(Solution.committed().size() == 1, "capacity two threshold must be one");

        Solution.configure(Integer.MAX_VALUE, 1);
        Solution.Command low = new Solution.Command("low", 1);
        Solution.add(low);
        check(Solution.committed().isEmpty(), "maximum capacity threshold must not overflow to a non-positive value");
        check(Solution.flush().equals(List.of(low)), "maximum capacity low-weight command should remain buffered");
        int maximumThreshold = 1_073_741_824;
        Solution.Command atThreshold = new Solution.Command("at-threshold", maximumThreshold);
        Solution.add(atThreshold);
        List<Solution.Command> maximumCommitted = Solution.committed();
        check(maximumCommitted.size() == 2 && maximumCommitted.get(0) == low && maximumCommitted.get(1) == atThreshold, "maximum capacity threshold arithmetic is incorrect");

        int nearMaximumCapacity = Integer.MAX_VALUE - 1;
        int nearMaximumThreshold = 1_073_741_823;
        Solution.configure(nearMaximumCapacity, 1);
        Solution.Command belowThreshold = new Solution.Command("below-threshold", nearMaximumThreshold - 1);
        Solution.Command overflowPush = new Solution.Command("overflow-push", nearMaximumCapacity);
        Solution.add(belowThreshold);
        check(Solution.committed().isEmpty(), "near-maximum buffer should remain below threshold");
        Solution.add(overflowPush);
        List<Solution.Command> overflowCommitted = Solution.committed();
        check(overflowCommitted.size() == 2 && overflowCommitted.get(0) == belowThreshold && overflowCommitted.get(1) == overflowPush, "buffered weight arithmetic must not overflow");
    }
}

