import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class Solution {
    private Solution() {}

    public static final class Entry {
        public final long id;
        public final String group;
        public final int state;
        public final int points;

        public Entry(long id, String group, int state, int points) {
            if (group == null || group.isEmpty()) throw new IllegalArgumentException("group");
            if (state != 0 && state != 1) throw new IllegalArgumentException("state");
            if (points < 0) throw new IllegalArgumentException("points");
            this.id = id;
            this.group = group;
            this.state = state;
            this.points = points;
        }
    }

    private static void check(List<Entry> entries) {
        if (entries == null) throw new IllegalArgumentException("entries");
        Set<Long> ids = new HashSet<>();
        for (Entry entry : entries) {
            if (entry == null) throw new IllegalArgumentException("null entry");
            if (!ids.add(entry.id)) throw new IllegalArgumentException("duplicate id");
        }
    }

    private static List<Entry> snapshot(List<Entry> entries) {
        return Collections.unmodifiableList(new ArrayList<>(entries));
    }

    public static List<Entry> add(List<Entry> entries, Entry entry) {
        check(entries);
        if (entry == null) throw new IllegalArgumentException("entry");
        for (Entry current : entries) {
            if (current.id == entry.id) throw new IllegalArgumentException("duplicate id");
        }
        ArrayList<Entry> result = new ArrayList<>(entries);
        result.add(entry);
        return snapshot(result);
    }

    public static List<Entry> remove(List<Entry> entries, long id) {
        check(entries);
        ArrayList<Entry> result = new ArrayList<>();
        for (Entry entry : entries) if (entry.id != id) result.add(entry);
        return snapshot(result);
    }

    public static List<Entry> updateState(List<Entry> entries, long id, int state) {
        check(entries);
        if (state != 0 && state != 1) throw new IllegalArgumentException("state");
        ArrayList<Entry> result = new ArrayList<>();
        for (Entry entry : entries) {
            result.add(entry.id == id
                    ? new Entry(entry.id, entry.group, state, entry.points)
                    : entry);
        }
        return snapshot(result);
    }

    public static Entry find(List<Entry> entries, long id) {
        check(entries);
        for (Entry entry : entries) if (entry.id == id) return entry;
        return null;
    }

    public static List<Entry> inGroup(List<Entry> entries, String group) {
        check(entries);
        if (group == null) throw new IllegalArgumentException("group");
        ArrayList<Entry> result = new ArrayList<>();
        for (Entry entry : entries) if (entry.group.equals(group)) result.add(entry);
        return snapshot(result);
    }

    public static long completedPoints(List<Entry> entries) {
        check(entries);
        long sum = 0L;
        for (Entry entry : entries) if (entry.state == 1) sum += entry.points;
        return sum;
    }
}

