import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("expected IllegalArgumentException");
    }

    private static void expectUOE(Runnable action) {
        try { action.run(); } catch (UnsupportedOperationException expected) { return; }
        throw new AssertionError("expected UnsupportedOperationException");
    }

    private static boolean same(Solution.Entry entry, long id, String group, int state, int points) {
        return entry != null && entry.id == id && entry.group.equals(group) && entry.state == state && entry.points == points;
    }

    public static void main(String[] args) {
        Solution.Entry a = new Solution.Entry(1L, "A", 0, 10);
        Solution.Entry b = new Solution.Entry(2L, "A", 1, 20);
        Solution.Entry c = new Solution.Entry(3L, "a", 1, 7);
        check(same(a, 1L, "A", 0, 10), "public fields incorrect");
        expectIAE(() -> new Solution.Entry(1L, null, 0, 0));
        expectIAE(() -> new Solution.Entry(1L, "", 0, 0));
        expectIAE(() -> new Solution.Entry(1L, "A", -1, 0));
        expectIAE(() -> new Solution.Entry(1L, "A", 2, 0));
        expectIAE(() -> new Solution.Entry(1L, "A", 0, -1));

        ArrayList<Solution.Entry> source = new ArrayList<>(List.of(a, b));
        List<Solution.Entry> added = Solution.add(source, c);
        check(added.size() == 3, "add size incorrect");
        check(same(added.get(0), 1L, "A", 0, 10) && same(added.get(1), 2L, "A", 1, 20) && same(added.get(2), 3L, "a", 1, 7), "add order or fields incorrect");
        check(source.size() == 2, "add must not mutate input");
        source.clear();
        check(added.size() == 3, "returned list must be independent");
        expectUOE(() -> added.remove(0));
        expectIAE(() -> Solution.add(added, new Solution.Entry(2L, "X", 0, 0)));

        List<Solution.Entry> removed = Solution.remove(added, 2L);
        check(removed.size() == 2 && same(removed.get(0), 1L, "A", 0, 10) && same(removed.get(1), 3L, "a", 1, 7), "remove order incorrect");
        List<Solution.Entry> missingRemoval = Solution.remove(removed, 99L);
        check(missingRemoval != removed && missingRemoval.size() == 2, "missing removal needs an independent equivalent list");
        check(same(missingRemoval.get(0), 1L, "A", 0, 10) && same(missingRemoval.get(1), 3L, "a", 1, 7), "missing removal changed entries");
        expectUOE(() -> missingRemoval.add(b));

        List<Solution.Entry> updated = Solution.updateState(added, 1L, 1);
        check(updated.size() == 3, "update size incorrect");
        check(same(updated.get(0), 1L, "A", 1, 10), "updated entry fields incorrect");
        check(same(a, 1L, "A", 0, 10), "input entry must remain unchanged");
        check(same(updated.get(1), 2L, "A", 1, 20) && same(updated.get(2), 3L, "a", 1, 7), "unmatched entries or order changed");
        List<Solution.Entry> missingUpdate = Solution.updateState(added, 100L, 0);
        check(missingUpdate != added && missingUpdate.size() == added.size(), "missing update needs independent list");
        check(same(missingUpdate.get(0), 1L, "A", 0, 10) && same(missingUpdate.get(1), 2L, "A", 1, 20) && same(missingUpdate.get(2), 3L, "a", 1, 7), "missing update changed entries");
        expectIAE(() -> Solution.updateState(added, 1L, 2));

        check(same(Solution.find(added, 2L), 2L, "A", 1, 20), "find existing failed");
        check(Solution.find(added, 99L) == null, "find absent must return null");
        List<Solution.Entry> group = Solution.inGroup(added, "A");
        check(group.size() == 2 && same(group.get(0), 1L, "A", 0, 10) && same(group.get(1), 2L, "A", 1, 20), "group filtering or order failed");
        List<Solution.Entry> lowerGroup = Solution.inGroup(added, "a");
        check(lowerGroup.size() == 1 && same(lowerGroup.get(0), 3L, "a", 1, 7), "group matching must be case-sensitive");
        expectUOE(() -> group.clear());
        check(Solution.completedPoints(added) == 27L, "completed points incorrect");
        check(Solution.completedPoints(List.of(new Solution.Entry(8L, "x", 1, Integer.MAX_VALUE), new Solution.Entry(9L, "x", 1, Integer.MAX_VALUE))) == 4294967294L, "sum must use long arithmetic");

        expectIAE(() -> Solution.add(null, a));
        expectIAE(() -> Solution.add(List.of(), null));
        expectIAE(() -> Solution.remove(null, 1L));
        expectIAE(() -> Solution.updateState(null, 1L, 0));
        expectIAE(() -> Solution.find(null, 1L));
        expectIAE(() -> Solution.inGroup(added, null));
        expectIAE(() -> Solution.completedPoints(null));
        List<Solution.Entry> withNull = Arrays.asList(a, null);
        expectIAE(() -> Solution.add(withNull, c));
        expectIAE(() -> Solution.remove(withNull, 99L));
        expectIAE(() -> Solution.updateState(withNull, 99L, 0));
        expectIAE(() -> Solution.find(withNull, 99L));
        expectIAE(() -> Solution.inGroup(withNull, "missing"));
        expectIAE(() -> Solution.completedPoints(withNull));

        Solution.Entry duplicateFirst = new Solution.Entry(10L, "dup", 0, 3);
        Solution.Entry duplicateSecond = new Solution.Entry(10L, "dup", 1, 4);
        List<Solution.Entry> duplicateIds = List.of(duplicateFirst, duplicateSecond);
        expectIAE(() -> Solution.add(duplicateIds, new Solution.Entry(11L, "new", 0, 1)));
        expectIAE(() -> Solution.remove(duplicateIds, 10L));
        expectIAE(() -> Solution.remove(duplicateIds, 99L));
        expectIAE(() -> Solution.updateState(duplicateIds, 10L, 1));
        expectIAE(() -> Solution.updateState(duplicateIds, 99L, 1));
        expectIAE(() -> Solution.find(duplicateIds, 10L));
        expectIAE(() -> Solution.find(duplicateIds, 99L));
        expectIAE(() -> Solution.inGroup(duplicateIds, "dup"));
        expectIAE(() -> Solution.inGroup(duplicateIds, "missing"));
        expectIAE(() -> Solution.completedPoints(duplicateIds));
    }
}

