import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.GZIPOutputStream;

public class SolutionTest {
    private static final Solution.TextCodec<String> STRING_CODEC = new Solution.TextCodec<>() {
        public String encode(String value) { return value; }
        public String decode(String text) { return text; }
    };

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("expected IllegalArgumentException");
    }

    private static byte[] gzip(byte[] frame) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (GZIPOutputStream gzip = new GZIPOutputStream(bytes)) {
                gzip.write(frame);
            }
            return bytes.toByteArray();
        } catch (IOException e) {
            throw new AssertionError(e);
        }
    }

    private static byte[] frame(int count, int length, byte[] data, byte[] trailing) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            DataOutputStream out = new DataOutputStream(bytes);
            out.writeInt(count);
            if (count > 0) {
                out.writeInt(length);
                if (data != null) out.write(data);
            }
            if (trailing != null) out.write(trailing);
            out.flush();
            return gzip(bytes.toByteArray());
        } catch (IOException e) {
            throw new AssertionError(e);
        }
    }

    public static void main(String[] args) {
        ArrayList<String> values = new ArrayList<>(List.of("", "héllo", "\uD83D\uDE00"));
        byte[] packed = Solution.pack(values, STRING_CODEC);
        values.clear();
        List<String> unpacked = Solution.unpack(packed, STRING_CODEC);
        check(unpacked.equals(List.of("", "héllo", "\uD83D\uDE00")), "UTF-8 round trip or order failed");
        unpacked.add("mutable");
        check(unpacked.size() == 4, "unpack must return a mutable list");
        check(Solution.unpack(Solution.pack(List.of(), STRING_CODEC), STRING_CODEC).isEmpty(), "empty batch failed");

        byte[] originalPacked = Solution.pack(List.of("stable"), STRING_CODEC);
        byte[] independentPacked = Solution.pack(List.of("stable"), STRING_CODEC);
        List<String> decoded = Solution.unpack(originalPacked, STRING_CODEC);
        originalPacked[0] ^= 1;
        check(decoded.equals(List.of("stable")), "decoded list must not alias packed bytes");
