Implement a CommonJS module exporting exactly `{ selectCandidates }`.

`selectCandidates(candidates, criteria)` validates, filters, and orders candidate records. Each candidate must be a non-null non-array object with:
- `id`: a non-empty string after trimming, unique after trimming;
- `name`: a non-empty string after trimming;
- `score`: a finite number from `0` through `100`;
- `skills`: an array of non-empty strings after trimming, with no duplicates after trimming.

`criteria` must be a non-null non-array object with exactly usable fields:
- `minScore`: optional finite number from `0` through `100`, default `0`;
- `requiredSkills`: optional array validated like candidate skills, default `[]`;
- `order`: optional one of `"name"`, `"score-asc"`, or `"score-desc"`, default `"name"`.

A candidate matches only if its score is at least `minScore` and it contains every required skill, using case-sensitive comparison. Sort names by JavaScript string comparison. Equal sort keys retain original input order. Return fresh normalized candidate objects with fresh skills arrays. Empty input returns `[]`. Throw `TypeError` for invalid types/shapes and `RangeError` for bounds, duplicates, or unsupported ordering. Do not mutate any argument.

Provide one complete source file using `module.exports`.

Return only the complete source file; do not include Markdown fences or prose.

'use strict';

function selectCandidates(candidates, criteria) {
  if (!Array.isArray(candidates)) throw new TypeError('candidates must be an array');
  if (criteria === null || typeof criteria !== 'object' || Array.isArray(criteria)) {
    throw new TypeError('criteria must be an object');
  }

  function text(value, field) {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new TypeError(field + ' must be a non-empty string');
    }
    return value.trim();
  }
  function skills(value) {
    if (!Array.isArray(value)) throw new TypeError('skills must be an array');
    const result = [];
    const seen = new Set();
    for (let index = 0; index < value.length; index += 1) {
      const item = text(value[index], 'skill');
      if (seen.has(item)) throw new RangeError('duplicate skill');
      seen.add(item);
      result.push(item);
    }
    return result;
  }
  function score(value, field) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(field + ' must be a finite number');
    }
    if (value < 0 || value > 100) throw new RangeError(field + ' is out of range');
    return value;
  }

  const minScore = Object.prototype.hasOwnProperty.call(criteria, 'minScore')
    ? score(criteria.minScore, 'minScore') : 0;
  const required = Object.prototype.hasOwnProperty.call(criteria, 'requiredSkills')
    ? skills(criteria.requiredSkills) : [];
  const order = Object.prototype.hasOwnProperty.call(criteria, 'order')
    ? criteria.order : 'name';
  if (!['name', 'score-asc', 'score-desc'].includes(order)) {
    throw new RangeError('unsupported order');
  }

  const ids = new Set();
  const normalized = [];
  for (let index = 0; index < candidates.length; index += 1) {
    const candidate = candidates[index];
    if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) {
      throw new TypeError('candidate must be an object');
    }
    const id = text(candidate.id, 'id');
    if (ids.has(id)) throw new RangeError('duplicate candidate id');
    ids.add(id);
    normalized.push({
      id,
      name: text(candidate.name, 'name'),
      score: score(candidate.score, 'score'),
      skills: skills(candidate.skills),
      index
    });
  }

  const selected = normalized.filter((candidate) =>
    candidate.score >= minScore &&
    required.every((skill) => candidate.skills.includes(skill))
  );
  selected.sort((a, b) => {
    let comparison;
    if (order === 'name') comparison = a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
    else if (order === 'score-asc') comparison = a.score - b.score;
    else comparison = b.score - a.score;
    return comparison || a.index - b.index;
  });
  return selected.map(({ id, name, score: value, skills: list }) =>
    ({ id, name, score: value, skills: [...list] }));
}

module.exports = { selectCandidates };

