'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['selectCandidates']);
const { selectCandidates } = api;

const candidates = [
  { id: '  b2 ', name: ' Zoe ', score: 80, skills: [' JS ', 'SQL'] },
  { id: 'a1', name: ' Amy ', score: 80, skills: ['JS', 'SQL', 'Go'] },
  { id: 'c3', name: 'Amy', score: 90, skills: ['JS'] },
  { id: 'd4', name: 'Low', score: 49, skills: ['JS', 'SQL'] }
];
const original = JSON.parse(JSON.stringify(candidates));
const selected = selectCandidates(candidates, { minScore: 50, requiredSkills: [' JS ', 'SQL'], order: 'score-desc' });
assert.deepStrictEqual(selected, [
  { id: 'b2', name: 'Zoe', score: 80, skills: ['JS', 'SQL'] },
  { id: 'a1', name: 'Amy', score: 80, skills: ['JS', 'SQL', 'Go'] }
]);
assert.deepStrictEqual(candidates, original);
assert.notStrictEqual(selected[0], candidates[0]);
assert.notStrictEqual(selected[0].skills, candidates[0].skills);

assert.deepStrictEqual(selectCandidates(candidates, { order: 'name' }).map((item) => item.id), ['a1', 'c3', 'd4', 'b2']);
assert.deepStrictEqual(selectCandidates(candidates, { order: 'score-asc' }).map((item) => item.id), ['d4', 'b2', 'a1', 'c3']);
assert.deepStrictEqual(selectCandidates([], {}), []);
assert.deepStrictEqual(selectCandidates([
  { id: 'zero', name: 'Zero', score: 0, skills: [] },
  { id: 'max', name: 'Max', score: 100, skills: [] }
], { minScore: 100 }).map((item) => item.id), ['max']);

assert.throws(() => selectCandidates(null, {}), TypeError);
assert.throws(() => selectCandidates([], null), TypeError);
assert.throws(() => selectCandidates([null], {}), TypeError);
assert.throws(() => selectCandidates([{ id: ' ', name: 'A', score: 1, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'a', name: '\t', score: 1, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: NaN, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: Infinity, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: -1, skills: [] }], {}), RangeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: 101, skills: [] }], {}), RangeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: 1, skills: [' '] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: 1, skills: ['JS', ' JS '] }], {}), RangeError);
assert.throws(() => selectCandidates([
  { id: ' x ', name: 'A', score: 1, skills: [] },
  { id: 'x', name: 'B', score: 2, skills: [] }
], {}), RangeError);

const sparseCandidates = new Array(1);
assert.throws(() => selectCandidates(sparseCandidates, {}), TypeError);
const sparseSkills = new Array(1);
assert.throws(() => selectCandidates([{ id: 'a', name: 'A', score: 1, skills: sparseSkills }], {}), TypeError);
const sparseRequired = new Array(1);
assert.throws(() => selectCandidates([], { requiredSkills: sparseRequired }), TypeError);
assert.throws(() => selectCandidates([], { minScore: '0' }), TypeError);
assert.throws(() => selectCandidates([], { minScore: -1 }), RangeError);
assert.throws(() => selectCandidates([], { minScore: 101 }), RangeError);
assert.throws(() => selectCandidates([], { requiredSkills: ['JS', ' JS '] }), RangeError);
assert.throws(() => selectCandidates([], { order: 'rank' }), RangeError);

