const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['moveRobot']);
const { moveRobot } = api;

const grid = [
  [0, 0, 1],
  [1, 0, 0],
  [0, 0, 0]
];
const position = { row: 1, column: 1 };
const gridBefore = grid.map((row) => row.slice());
const movedNorth = moveRobot(grid, position, 'N');
assert.deepStrictEqual(movedNorth, { row: 0, column: 1 });
assert.deepStrictEqual(Object.keys(movedNorth).sort(), ['column', 'row']);
assert.notStrictEqual(movedNorth, position);
assert.deepStrictEqual(position, { row: 1, column: 1 });
assert.deepStrictEqual(grid, gridBefore);

assert.deepStrictEqual(moveRobot(grid, position, 'S'), { row: 2, column: 1 });
assert.deepStrictEqual(moveRobot(grid, position, 'E'), { row: 1, column: 2 });
const blocked = moveRobot(grid, position, 'W');
assert.deepStrictEqual(blocked, position);
assert.notStrictEqual(blocked, position);

