from copy import deepcopy


def compile_reservation_views(events, reservations):
    if not isinstance(events, list) or not isinstance(reservations, list):
        raise ValueError("arguments must be lists")

    by_code = {}
    labels = set()
    by_label = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {"code", "label", "fee"}:
            raise ValueError("invalid event")
        code, label, fee = event["code"], event["label"], event["fee"]
        if not isinstance(code, str) or not code or code in by_code:
            raise ValueError("invalid event code")
        if not isinstance(label, str) or not label or label in labels:
            raise ValueError("invalid event label")
        if not isinstance(fee, int) or isinstance(fee, bool) or fee < 0:
            raise ValueError("invalid fee")
        stored = {"code": code, "label": label, "fee": fee}
        by_code[code] = stored
        labels.add(label)
        by_label[label] = []

    by_contact = {}
    for reservation in reservations:
        if not isinstance(reservation, dict) or set(reservation) != {
            "event_code", "party_size", "customer", "contact"
        }:
            raise ValueError("invalid reservation")
        code = reservation["event_code"]
        size = reservation["party_size"]
        customer = reservation["customer"]
        contact = reservation["contact"]
        if not isinstance(code, str) or not code:
            raise ValueError("invalid event code")
        if code not in by_code:
            raise ValueError("unknown event")
        if not isinstance(size, int) or isinstance(size, bool) or size <= 0:
            raise ValueError("invalid party size")
        if not isinstance(customer, str) or not customer:
            raise ValueError("invalid customer")
        if not isinstance(contact, str) or not contact:
            raise ValueError("invalid contact")
        event = by_code[code]
        by_contact.setdefault(contact, []).append(deepcopy({
            "code": code,
            "label": event["label"],
            "fee": event["fee"],
            "party_size": size,
        }))
        by_label[event["label"]].append(deepcopy({
            "customer": customer,
            "contact": contact,
            "party_size": size,
        }))

    return {"by_contact": by_contact, "by_label": by_label}

