from copy import deepcopy


def merge_identity(directory: dict, payload: dict) -> tuple[dict, dict]:
    if not isinstance(directory, dict):
        raise TypeError("directory must be a dict")
    for key, account in directory.items():
        if not isinstance(key, str) or not isinstance(account, dict):
            raise TypeError("malformed directory entry")
        if not {"username", "email", "password"} <= set(account):
            raise ValueError("account is missing required fields")

    if not isinstance(payload, dict):
        raise TypeError("payload must be a dict")
    if set(payload) != {"external_key", "email", "secret"}:
        raise ValueError("malformed payload")
    for value in payload.values():
        if not isinstance(value, str):
            raise TypeError("payload values must be strings")
        if not value:
            raise ValueError("payload values must be non-empty")

    key = payload["external_key"]
    result = deepcopy(directory)
    if key in result:
        result[key] = deepcopy(result[key])
        result[key]["email"] = payload["email"]
    else:
        result[key] = {
            "username": key,
            "email": payload["email"],
            "password": payload["secret"],
        }
    return result, result[key]

