import copy
import unittest

from solution import merge_identity


class MergeIdentityTests(unittest.TestCase):
    def test_add_to_empty_directory_and_identity_of_selected_account(self):
        directory = {}
        payload = {"external_key": "ext", "email": "new@example", "secret": "secret"}
        directory_before = copy.deepcopy(directory)
        payload_before = copy.deepcopy(payload)
        result, account = merge_identity(directory, payload)
        self.assertEqual(result, {
            "ext": {"username": "ext", "email": "new@example", "password": "secret"}
        })
        self.assertIs(account, result["ext"])
        self.assertEqual(directory, directory_before)
        self.assertEqual(payload, payload_before)

    def test_existing_account_updates_only_email_and_deep_copies_everything(self):
        directory = {
            "target": {
                "username": "user",
                "email": "old@example",
                "password": "old-secret",
                "profile": {"tags": ["a", "b"]},
            },
            "other": {
                "username": "other-user",
                "email": "other@example",
                "password": "other-secret",
                "settings": {"alerts": [True]},
            },
        }
        payload = {"external_key": "target", "email": "new@example", "secret": "ignored"}
        before = copy.deepcopy(directory)
        payload_before = copy.deepcopy(payload)
        result, account = merge_identity(directory, payload)
        self.assertEqual(result["target"], {
            "username": "user",
            "email": "new@example",
            "password": "old-secret",
            "profile": {"tags": ["a", "b"]},
        })
        self.assertEqual(result["other"], directory["other"])
        self.assertIs(account, result["target"])
        self.assertIsNot(result, directory)
        self.assertIsNot(result["target"], directory["target"])
        self.assertIsNot(result["other"], directory["other"])
        self.assertIsNot(result["target"]["profile"], directory["target"]["profile"])
        self.assertIsNot(result["target"]["profile"]["tags"], directory["target"]["profile"]["tags"])
        self.assertIsNot(result["other"]["settings"], directory["other"]["settings"])
        result["target"]["profile"]["tags"].append("changed")
        result["other"]["settings"]["alerts"].append(False)
        self.assertEqual(directory, before)
        self.assertEqual(payload, payload_before)

    def test_shared_account_under_two_keys_updates_only_selected_key(self):
        shared = {
            "username": "shared-user",
            "email": "old@example",
            "password": "password",
            "profile": {"tags": ["one"]},
        }
        directory = {"target": shared, "other": shared}
        payload = {"external_key": "target", "email": "new@example", "secret": "ignored"}
        before = copy.deepcopy(directory)
        result, account = merge_identity(directory, payload)
        self.assertIs(account, result["target"])
        self.assertEqual(result["target"]["email"], "new@example")
        self.assertEqual(result["other"]["email"], "old@example")
        self.assertEqual(result["other"], before["other"])
        self.assertIsNot(result["target"], result["other"])
        self.assertIsNot(result["target"], shared)
        self.assertIsNot(result["other"], shared)
        self.assertEqual(directory, before)
        self.assertEqual(shared["email"], "old@example")

    def test_new_account_does_not_alias_preexisting_nested_values(self):
        directory = {
            "old": {
                "username": "u",
                "email": "e",
                "password": "p",
                "nested": [{"x": 1}],
            }
        }
        result, account = merge_identity(
            directory,
            {"external_key": "new", "email": "n@example", "secret": "s"},
        )
        self.assertIs(account, result["new"])
        self.assertIsNot(result["old"]["nested"], directory["old"]["nested"])
        self.assertIsNot(result["old"]["nested"][0], directory["old"]["nested"][0])

    def test_payload_must_have_exact_nonempty_string_fields(self):
        valid_directory = {}
        malformed = [
            None,
            [],
            {},
            {"external_key": "x", "email": "e"},
            {"external_key": "x", "email": "e", "secret": "s", "extra": "v"},
            {"external_key": "", "email": "e", "secret": "s"},
            {"external_key": "x", "email": "", "secret": "s"},
            {"external_key": "x", "email": "e", "secret": ""},
            {"external_key": 1, "email": "e", "secret": "s"},
            {"external_key": "x", "email": 1, "secret": "s"},
            {"external_key": "x", "email": "e", "secret": 1},
        ]
        for payload in malformed:
            with self.subTest(payload=payload), self.assertRaises((TypeError, ValueError)):
                merge_identity(valid_directory, payload)

    def test_directory_validation(self):
        payload = {"external_key": "x", "email": "e", "secret": "s"}
        malformed = [
            None,
            [],
            {1: {"username": "u", "email": "e", "password": "p"}},
            {"x": []},
            {"x": {"username": "u", "email": "e"}},
            {"x": {"username": "u", "password": "p"}},
            {"x": {"email": "e", "password": "p"}},
        ]
        for directory in malformed:
            with self.subTest(directory=directory), self.assertRaises((TypeError, ValueError)):
                merge_identity(directory, payload)

    def test_all_accounts_are_validated_even_when_target_is_new(self):
        directory = {
            "valid": {"username": "u", "email": "e", "password": "p"},
            "broken": {"username": "u", "email": "e"},
        }
        before = copy.deepcopy(directory)
        with self.assertRaises((TypeError, ValueError)):
            merge_identity(directory, {"external_key": "new", "email": "n", "secret": "s"})
        self.assertEqual(directory, before)

    def test_failure_does_not_mutate_inputs(self):
        directory = {
            "x": {
                "username": "u",
                "email": "old",
                "password": "p",
                "nested": {"values": [1, 2]},
            }
        }
        payload = {"external_key": "x", "email": "", "secret": "s"}
        directory_before = copy.deepcopy(directory)
        payload_before = copy.deepcopy(payload)
        with self.assertRaises((TypeError, ValueError)):
            merge_identity(directory, payload)
        self.assertEqual(directory, directory_before)
        self.assertEqual(payload, payload_before)


