use std::collections::{BTreeMap, BTreeSet};

pub struct LinkGraph {
    pub outgoing: BTreeMap<String, Vec<String>>,
}

pub fn normalize_locator(input: &str) -> Result<String, String> {
    if input.is_empty() {
        return Err("locator is empty".to_string());
    }
    if input.chars().any(char::is_whitespace) {
        return Err("locator contains whitespace".to_string());
    }
    if let Some(pos) = input.find(':') {
        let scheme = &input[..pos];
        let mut chars = scheme.chars();
        if !matches!(chars.next(), Some(c) if c.is_ascii_alphabetic())
            || !chars.all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '.'))
        {
            return Err("invalid locator scheme".to_string());
        }
        Ok(input.to_string())
    } else {
        Ok(format!("local:{input}"))
    }
}

pub fn natural_join(parts: &[String]) -> String {
    match parts.len() {
        0 => String::new(),
        1 => parts[0].clone(),
        2 => format!("{} and {}", parts[0], parts[1]),
        n => format!("{}, and {}", parts[..n - 1].join(", "), parts[n - 1]),
    }
}

pub fn source_nodes(candidates: &[String], graph: &LinkGraph) -> Vec<String> {
    let incoming: BTreeSet<&str> = graph
        .outgoing
        .values()
        .flat_map(|targets| targets.iter().map(String::as_str))
        .collect();
    let mut seen = BTreeSet::new();
    candidates
        .iter()
        .filter(|name| seen.insert(name.as_str()) && !incoming.contains(name.as_str()))
        .cloned()
        .collect()
}

fn quoted(value: &str) -> String {
    let mut out = String::from("\"");
    for ch in value.chars() {
        match ch {
            '\"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if c <= '\u{1f}' => {
                use std::fmt::Write;
                write!(&mut out, "\\u{:04x}", c as u32).unwrap();
            }
            c => out.push(c),
        }
    }
    out.push('\"');
    out
}

pub fn render_string_map(map: &BTreeMap<String, String>) -> String {
    let entries: Vec<String> = map
        .iter()
        .map(|(key, value)| format!("{}:{}", quoted(key), quoted(value)))
        .collect();
    format!("{{{}}}", entries.join(","))
}

pub fn render_list_map(map: &BTreeMap<String, Vec<String>>) -> String {
    let entries: Vec<String> = map
        .iter()
        .map(|(key, value)| format!("{}:{}", quoted(key), render_string_list(value)))
        .collect();
    format!("{{{}}}", entries.join(","))
}

pub fn render_string_list(values: &[String]) -> String {
    let entries: Vec<String> = values.iter().map(|value| quoted(value)).collect();
    format!("[{}]", entries.join(","))
}

