#[path = "solution.rs"]
mod solution;

use std::collections::BTreeMap;
use solution::{
    natural_join, normalize_locator, render_list_map, render_string_list,
    render_string_map, source_nodes, LinkGraph,
};

fn canonical_json(text: &str) -> String {
    use std::fmt::Write;

    let mut chars = text.chars();
    let mut output = String::new();
    let mut in_string = false;

    while let Some(ch) = chars.next() {
        if !in_string {
            output.push(ch);
            if ch == '"' {
                in_string = true;
            }
            continue;
        }

        match ch {
            '"' => {
                output.push(ch);
                in_string = false;
            }
            '\\' => {
                let escape = chars.next().expect("incomplete JSON escape");
                let decoded = match escape {
                    '"' => '"',
                    '\\' => '\\',
                    '/' => '/',
                    'b' => '\u{0008}',
                    'f' => '\u{000c}',
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    'u' => {
                        let mut digits = String::new();
                        for _ in 0..4 {
                            digits.push(chars.next().expect("incomplete Unicode escape"));
                        }
                        let value = u32::from_str_radix(&digits, 16)
                            .expect("invalid Unicode escape");
                        char::from_u32(value).expect("invalid Unicode scalar")
                    }
                    other => panic!("invalid JSON escape: {other:?}"),
                };

                match decoded {
                    '"' => output.push_str("\\\""),
                    '\\' => output.push_str("\\\\"),
                    '\n' => output.push_str("\\n"),
                    '\r' => output.push_str("\\r"),
                    '\t' => output.push_str("\\t"),
                    control if control <= '\u{001f}' => {
                        write!(output, "\\u{:04x}", control as u32).unwrap();
                    }
                    other => output.push(other),
                }
            }
            other => output.push(other),
        }
    }

    assert!(!in_string, "unterminated JSON string");
    output
}

#[test]
fn locator_normalization_handles_local_and_explicit_schemes() {
    assert_eq!(normalize_locator("folder/item").unwrap(), "local:folder/item");
    assert_eq!(normalize_locator("A+1.-z:value:rest").unwrap(), "A+1.-z:value:rest");
}

#[test]
fn locator_normalization_rejects_empty_whitespace_and_bad_schemes() {
    for input in [
        "",
        " ",
        "local:has space",
        "local:\thas-tab",
        ":value",
        "1http:value",
        "a_b:value",
        "+abc:value",
    ] {
        assert!(normalize_locator(input).is_err(), "accepted {input:?}");
    }
}

#[test]
fn natural_join_covers_all_shapes_without_mutation() {
    let empty: Vec<String> = vec![];
    assert_eq!(natural_join(&empty), "");

    let one = vec!["a".to_string()];
    assert_eq!(natural_join(&one), "a");

    let two = vec!["a".to_string(), "b".to_string()];
    assert_eq!(natural_join(&two), "a and b");

    let many = vec!["a".to_string(), "b".to_string(), "c".to_string()];
    let before = many.clone();
    assert_eq!(natural_join(&many), "a, b, and c");
    assert_eq!(many, before);
}

#[test]
fn source_nodes_consider_all_graph_nodes_self_edges_and_candidate_duplicates() {
    let mut outgoing = BTreeMap::new();
    outgoing.insert("outside".to_string(), vec!["b".to_string()]);
    outgoing.insert("a".to_string(), vec!["a".to_string(), "missing".to_string()]);
    outgoing.insert("c".to_string(), vec![]);
    let graph = LinkGraph { outgoing };
    let candidates = vec![
        "c".to_string(),
        "a".to_string(),
        "b".to_string(),
        "c".to_string(),
        "d".to_string(),
        "d".to_string(),
    ];
    let before = candidates.clone();

    assert_eq!(source_nodes(&candidates, &graph), vec!["c", "d"]);
    assert_eq!(candidates, before);
}

#[test]
fn source_nodes_with_empty_inputs_are_empty() {
    let graph = LinkGraph {
        outgoing: BTreeMap::new(),
    };
    assert!(source_nodes(&[], &graph).is_empty());
}

#[test]
fn renders_string_list_as_compact_json_with_required_escaping() {
    let values = vec![
        "quote\"".to_string(),
        "slash\\".to_string(),
        "line\nreturn\rtab\t".to_string(),
    ];
    assert_eq!(
        render_string_list(&values),
        "[\"quote\\\"\",\"slash\\\\\",\"line\\nreturn\\rtab\\t\"]"
    );
    assert_eq!(render_string_list(&[]), "[]");
}

#[test]
fn renders_maps_in_btree_key_order_and_vectors_in_input_order() {
    let mut strings = BTreeMap::new();
    strings.insert("z".to_string(), "last".to_string());
    strings.insert("a\"".to_string(), "first\\\n".to_string());
    assert_eq!(
        render_string_map(&strings),
        "{\"a\\\"\":\"first\\\\\\n\",\"z\":\"last\"}"
    );

    let mut lists = BTreeMap::new();
    lists.insert("b".to_string(), vec!["2".to_string(), "1".to_string()]);
    lists.insert("a".to_string(), vec![]);
    assert_eq!(render_list_map(&lists), "{\"a\":[],\"b\":[\"2\",\"1\"]}");
    assert_eq!(render_string_map(&BTreeMap::new()), "{}");
    assert_eq!(render_list_map(&BTreeMap::new()), "{}");
}

#[test]
fn all_renderers_escape_additional_json_control_characters() {
    let values = vec![
        "\0".to_string(),
        "\u{0008}".to_string(),
        "\u{000c}".to_string(),
        "\u{001f}".to_string(),
    ];
    assert_eq!(
        canonical_json(&render_string_list(&values)),
        "[\"\\u0000\",\"\\u0008\",\"\\u000c\",\"\\u001f\"]"
    );

    let mut strings = BTreeMap::new();
    strings.insert("\0".to_string(), "\u{0008}".to_string());
    strings.insert("\u{000c}".to_string(), "\u{001f}".to_string());
    assert_eq!(
        canonical_json(&render_string_map(&strings)),
        "{\"\\u0000\":\"\\u0008\",\"\\u000c\":\"\\u001f\"}"
    );

    let mut lists = BTreeMap::new();
    lists.insert(
        "\u{0008}".to_string(),
        vec!["\0".to_string(), "\u{000c}".to_string(), "\u{001f}".to_string()],
    );
    assert_eq!(
        canonical_json(&render_list_map(&lists)),
        "{\"\\u0008\":[\"\\u0000\",\"\\u000c\",\"\\u001f\"]}"
    );
}

