pub fn compile_documents(documents: &[NamedDocument], id_document: &str) -> Result<Compilation, CompileError> {
    let mut cache: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
    for document in documents {
        if document.name.is_empty() { return Err(CompileError::EmptyName); }
        if cache.contains_key(&document.name) { return Err(CompileError::DuplicateName(document.name.clone())); }
