#[path = "solution.rs"]
mod solution;

use solution::{compile_documents, CompileError, NamedDocument};

fn document(name: &str, body: &str) -> NamedDocument {
    NamedDocument {
        name: name.to_string(),
        body: body.to_string(),
    }
}

fn canonical_json(text: &str) -> String {
    use std::fmt::Write;

    let mut chars = text.chars();
    let mut output = String::new();
    let mut in_string = false;

    while let Some(ch) = chars.next() {
        if !in_string {
            output.push(ch);
            if ch == '"' {
                in_string = true;
            }
            continue;
        }

        match ch {
            '"' => {
                output.push(ch);
                in_string = false;
            }
            '\\' => {
                let escape = chars.next().expect("incomplete JSON escape");
                let decoded = match escape {
                    '"' => '"',
                    '\\' => '\\',
                    '/' => '/',
                    'b' => '\u{0008}',
                    'f' => '\u{000c}',
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    'u' => {
                        let mut digits = String::new();
                        for _ in 0..4 {
                            digits.push(chars.next().expect("incomplete Unicode escape"));
                        }
                        let value = u32::from_str_radix(&digits, 16)
                            .expect("invalid Unicode escape");
                        char::from_u32(value).expect("invalid Unicode scalar")
                    }
                    other => panic!("invalid JSON escape: {other:?}"),
                };

                match decoded {
                    '"' => output.push_str("\\\""),
                    '\\' => output.push_str("\\\\"),
                    '\n' => output.push_str("\\n"),
                    '\r' => output.push_str("\\r"),
                    '\t' => output.push_str("\\t"),
                    control if control <= '\u{001f}' => {
                        write!(output, "\\u{:04x}", control as u32).unwrap();
                    }
                    other => output.push(other),
                }
            }
            other => output.push(other),
        }
    }

    assert!(!in_string, "unterminated JSON string");
    output
}

#[test]
fn empty_inputs_produce_direct_empty_cache_and_empty_ids() {
    let result = compile_documents(&[], "").unwrap();
    assert_eq!(result.cache_json, "{}");
    assert!(result.sorted_ids.is_empty());
}

#[test]
fn sorts_documents_and_entries_and_replaces_duplicate_keys() {
    let documents = vec![
        document("z", "b=old\na=first\nb=new=with=equals"),
        document("a", "y=2\nx=1"),
    ];
    let before = documents.clone();
    let result = compile_documents(&documents, "9\n 2 \n9\n1\n").unwrap();

    assert_eq!(
        result.cache_json,
        "{\"a\":{\"x\":\"1\",\"y\":\"2\"},\"z\":{\"a\":\"first\",\"b\":\"new=with=equals\"}}"
    );
    assert_eq!(result.sorted_ids, vec![1, 2, 9]);
    assert_eq!(documents, before);
}

#[test]
fn empty_values_are_valid_and_empty_documents_render_as_objects() {
    let documents = vec![document("empty", ""), document("value", "key=")];
    let result = compile_documents(&documents, "\n \t\n").unwrap();
    assert_eq!(result.cache_json, "{\"empty\":{},\"value\":{\"key\":\"\"}}");
    assert!(result.sorted_ids.is_empty());
}

#[test]
fn json_escapes_names_keys_and_values() {
    let documents = vec![document("n\"\\\n\r\t", "k\"\\\t=v\"\\\t")];
    let result = compile_documents(&documents, "").unwrap();
    assert_eq!(
        result.cache_json,
        "{\"n\\\"\\\\\\n\\r\\t\":{\"k\\\"\\\\\\t\":\"v\\\"\\\\\\t\"}}"
    );
}

#[test]
fn json_escapes_additional_controls_in_names_keys_and_values() {
    let documents = vec![document("name\0", "key\u{0008}=value\u{000c}")];
    let result = compile_documents(&documents, "").unwrap();
    assert_eq!(
        canonical_json(&result.cache_json),
        "{\"name\\u0000\":{\"key\\u0008\":\"value\\u000c\"}}"
    );
}

#[test]
fn rejects_empty_and_duplicate_document_names() {
    assert_eq!(
        compile_documents(&[document("", "a=b")], ""),
        Err(CompileError::EmptyName)
    );
    assert_eq!(
        compile_documents(&[document("same", "a=1"), document("same", "b=2")], ""),
        Err(CompileError::DuplicateName("same".to_string()))
    );
}

#[test]
fn whitespace_only_names_are_not_the_empty_name() {
    let result = compile_documents(&[document(" ", "a=b")], "").unwrap();
    assert_eq!(result.cache_json, "{\" \":{\"a\":\"b\"}}");
}

#[test]
fn malformed_entries_report_document_and_one_based_line() {
    assert_eq!(
        compile_documents(&[document("doc", "ok=1\nmissing\nlater=2")], ""),
        Err(CompileError::MalformedEntry {
            document: "doc".to_string(),
            line: 2,
        })
    );
    assert_eq!(
        compile_documents(&[document("doc", "=value")], ""),
        Err(CompileError::MalformedEntry {
            document: "doc".to_string(),
            line: 1,
        })
    );
}

#[test]
fn ids_support_zero_and_u64_maximum_and_are_deduplicated() {
    let result = compile_documents(
        &[],
        "18446744073709551615\n0\n18446744073709551615\n",
    )
    .unwrap();
    assert_eq!(result.sorted_ids, vec![0, u64::MAX]);
}

#[test]
fn invalid_ids_report_the_original_one_based_line() {
    assert_eq!(
        compile_documents(&[], "1\n \nnot-a-number\n4"),
        Err(CompileError::InvalidId { line: 3 })
    );
    assert_eq!(
        compile_documents(&[], "18446744073709551616"),
        Err(CompileError::InvalidId { line: 1 })
    );
    assert_eq!(
        compile_documents(&[], "+1"),
        Err(CompileError::InvalidId { line: 1 })
    );
}

