#[path = "solution.rs"]
mod solution;

use solution::{parse_invocation, Command, Kind, ParseError};

#[test]
fn parses_each_command_and_default_workspace() {
    assert_eq!(
        parse_invocation(&["create", "module", "core"]).unwrap().command,
        Command::Create {
            kind: Kind::Module,
            name: "core".to_string(),
        }
    );
    assert_eq!(
        parse_invocation(&["create", "dashboard", "sales"]).unwrap().command,
        Command::Create {
            kind: Kind::Dashboard,
            name: "sales".to_string(),
        }
    );
    assert_eq!(
        parse_invocation(&["examine", "item"]).unwrap().command,
        Command::Examine {
            name: "item".to_string(),
        }
    );
    assert_eq!(
        parse_invocation(&["send", "item", "--replace"]).unwrap().command,
        Command::Send {
            name: "item".to_string(),
            replace: true,
        }
    );
    assert_eq!(parse_invocation(&["check"]).unwrap().command, Command::Check { jobs: 1 });
    assert_eq!(parse_invocation(&["check"]).unwrap().workspace, "data");
}

#[test]
fn global_workspace_is_only_consumed_before_the_command() {
    let invocation = parse_invocation(&["--workspace", "team", "examine", "doc"]).unwrap();
    assert_eq!(invocation.workspace, "team");
    assert_eq!(
        invocation.command,
        Command::Examine {
            name: "doc".to_string(),
        }
    );

    assert_eq!(
        parse_invocation(&["examine", "doc", "--workspace", "team"]),
        Err(ParseError::Unexpected("--workspace".to_string()))
    );
}

#[test]
fn bundle_retains_tag_order_empty_tags_and_flag_state() {
    let invocation = parse_invocation(&[
        "bundle",
        "app",
        "--tag",
        "first",
        "--optimized",
        "--tag",
        "",
        "--tag",
        "first",
    ])
    .unwrap();
    assert_eq!(
        invocation.command,
        Command::Bundle {
            name: "app".to_string(),
            optimized: true,
            tags: vec!["first".to_string(), "".to_string(), "first".to_string()],
        }
    );
}

#[test]
fn jobs_accepts_both_boundaries() {
    assert_eq!(
        parse_invocation(&["check", "--jobs", "1"]).unwrap().command,
        Command::Check { jobs: 1 }
    );
    assert_eq!(
        parse_invocation(&["check", "--jobs", "256"]).unwrap().command,
        Command::Check { jobs: 256 }
    );
}

#[test]
fn empty_unknown_words_and_command_position_options_are_distinguished() {
    assert_eq!(parse_invocation(&[]), Err(ParseError::MissingCommand));
    assert_eq!(
        parse_invocation(&["--workspace", "team"]),
        Err(ParseError::MissingCommand)
    );
    assert_eq!(
        parse_invocation(&["launch", "x"]),
        Err(ParseError::UnknownCommand("launch".to_string()))
    );
    assert_eq!(
        parse_invocation(&["--unknown"]),
        Err(ParseError::Unexpected("--unknown".to_string()))
    );
    assert_eq!(
        parse_invocation(&["--workspace", "team", "--unknown"]),
        Err(ParseError::Unexpected("--unknown".to_string()))
    );
}

#[test]
fn missing_option_operands_name_the_option() {
    assert_eq!(
        parse_invocation(&["--workspace"]),
        Err(ParseError::MissingValue("--workspace".to_string()))
    );
    assert_eq!(
        parse_invocation(&["bundle", "app", "--tag"]),
        Err(ParseError::MissingValue("--tag".to_string()))
    );
    assert_eq!(
        parse_invocation(&["check", "--jobs"]),
        Err(ParseError::MissingValue("--jobs".to_string()))
    );
}

#[test]
fn invalid_kinds_names_workspaces_and_jobs_are_rejected() {
    assert_eq!(
        parse_invocation(&["create", "service", "x"]),
        Err(ParseError::InvalidValue {
            option: "kind".to_string(),
            value: "service".to_string(),
        })
    );
    assert_eq!(
        parse_invocation(&["examine", ""]),
        Err(ParseError::InvalidValue {
            option: "name".to_string(),
            value: "".to_string(),
        })
    );
    assert_eq!(
        parse_invocation(&["--workspace", "", "check"]),
        Err(ParseError::InvalidValue {
            option: "--workspace".to_string(),
            value: "".to_string(),
        })
    );

    for value in ["0", "257", "65536", "-1", "abc"] {
        assert_eq!(
            parse_invocation(&["check", "--jobs", value]),
            Err(ParseError::InvalidValue {
                option: "--jobs".to_string(),
                value: value.to_string(),
            })
        );
    }
}

#[test]
fn single_use_options_reject_duplicates_but_tags_do_not() {
    assert_eq!(
        parse_invocation(&["--workspace", "a", "--workspace", "b", "check"]),
        Err(ParseError::DuplicateOption("--workspace".to_string()))
    );
    assert_eq!(
        parse_invocation(&["bundle", "x", "--optimized", "--optimized"]),
        Err(ParseError::DuplicateOption("--optimized".to_string()))
    );
    assert_eq!(
        parse_invocation(&["send", "x", "--replace", "--replace"]),
        Err(ParseError::DuplicateOption("--replace".to_string()))
    );
    assert_eq!(
        parse_invocation(&["check", "--jobs", "2", "--jobs", "3"]),
        Err(ParseError::DuplicateOption("--jobs".to_string()))
    );
}

#[test]
fn extra_positionals_and_unknown_or_misplaced_options_are_unexpected() {
    for args in [
        vec!["examine", "x", "extra"],
        vec!["send", "x", "--unknown"],
        vec!["check", "extra"],
        vec!["create", "module", "x", "extra"],
    ] {
        assert!(matches!(parse_invocation(&args), Err(ParseError::Unexpected(_))));
    }
}

#[test]
fn parsing_does_not_mutate_argument_storage() {
    let args = ["bundle", "app", "--tag", "x", "--optimized"];
    let before = args;
    let _ = parse_invocation(&args).unwrap();
    assert_eq!(args, before);
}

