import { DocumentSignal, type DocumentInfo } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: ${String(actual)}`);
}
function documentEqual(actual: DocumentInfo, title: string, tags: readonly string[], message: string): void {
  equal(actual.title, title, `${message} title`);
  assert(actual.tags.length === tags.length, `${message} tag count`);
  tags.forEach((tag, index) => equal(actual.tags[index], tag, `${message} tag ${index}`));
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const initial = { title: "  Plan  ", tags: [" alpha ", "", "alpha", "   "] };
const signal = new DocumentSignal(initial);
initial.title = "changed";
initial.tags[0] = "changed";
initial.tags.push("extra");
documentEqual(signal.value, "Plan", ["alpha", "", "alpha", ""], "constructor normalizes and copies");

const sparseConstructorTags = new Array<string>(2);
sparseConstructorTags[1] = "tag";
throwsTypeError(
  () => new DocumentSignal({ title: "Sparse", tags: sparseConstructorTags }),
  "sparse constructor tags rejected"
);

const firstRead = signal.value;
const secondRead = signal.value;
assert(firstRead !== secondRead, "getter returns a new document");
assert(firstRead.tags !== secondRead.tags, "getter returns a new tag array");
firstRead.title = "mutated";
firstRead.tags.push("mutated");
documentEqual(signal.value, "Plan", ["alpha", "", "alpha", ""], "getter mutation is isolated");

const calls: string[] = [];
let receivedOne: DocumentInfo | undefined;
let removeSecond = (): void => {};
const removeFirst = signal.subscribe((value) => {
  calls.push(`first:${value.title}`);
  receivedOne = value;
  value.title = "listener mutation";
  value.tags[0] = "listener mutation";
  removeSecond();
  signal.subscribe((later) => calls.push(`late:${later.title}`));
});
removeSecond = signal.subscribe((value) => {
  calls.push(`second:${value.title}:${value.tags[0]}`);
  assert(receivedOne !== value, "listeners receive distinct documents");
  assert(receivedOne?.tags !== value.tags, "listeners receive distinct arrays");
});
const replacement = { title: " Next ", tags: [" x ", "x", " "] };
signal.replace(replacement);
replacement.title = "outside";
replacement.tags[0] = "outside";
equal(calls.join("|"), "first:Next|second:Next:x", "notification snapshot and order");
documentEqual(signal.value, "Next", ["x", "x", ""], "replacement is copied");

calls.length = 0;
signal.replace({ title: "Again", tags: [] });
equal(calls.join("|"), "first:Again|late:Again", "listener changes apply to later notifications");
removeFirst();
removeFirst();
removeSecond();

const identitySignal = new DocumentSignal({ title: "Identity", tags: [] });
const identityCalls: string[] = [];
const listenerA = (): void => { identityCalls.push("A"); };
const listenerB = (): void => { identityCalls.push("B"); };
identitySignal.subscribe(listenerA);
identitySignal.subscribe(listenerB);
const removeLastA = identitySignal.subscribe(listenerA);
removeLastA();
removeLastA();
identitySignal.replace({ title: "Identity next", tags: [] });
equal(identityCalls.join("|"), "A|B", "unsubscribe removes only the selected duplicate registration");

const beforeInvalid = signal.value;
const notificationCount = calls.length;
throwsTypeError(() => signal.replace({ title: "   ", tags: ["ok"] }), "blank title rejected");
throwsTypeError(() => signal.replace({ title: "valid", tags: [1 as unknown as string] }), "non-string tag rejected");
const sparseReplacementTags = new Array<string>(2);
sparseReplacementTags[1] = "ok";
throwsTypeError(
  () => signal.replace({ title: "valid", tags: sparseReplacementTags }),
  "sparse replacement tags rejected"
);
documentEqual(signal.value, beforeInvalid.title, beforeInvalid.tags, "invalid replacement is atomic");
equal(calls.length, notificationCount, "invalid replacement does not notify");
throwsTypeError(() => new DocumentSignal({ title: "", tags: [] }), "empty constructor title rejected");
throwsTypeError(() => new DocumentSignal({ title: "ok", tags: null as unknown as string[] }), "malformed tags rejected");
throwsTypeError(() => signal.subscribe(null as unknown as (value: DocumentInfo) => void), "non-function listener rejected");

