import { buildWorkshopSubmission, type WorkshopDraft, type ValidationResult } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: ${String(actual)}`);
}
function errorsOf(result: ValidationResult): readonly string[] {
  assert(result.ok === false, "expected validation failure");
  return result.errors;
}
function oneError(input: WorkshopDraft, earliest: string, message: string): string {
  const errors = errorsOf(buildWorkshopSubmission(input, earliest));
  equal(errors.length, 1, message);
  return errors[0];
}

const valid: WorkshopDraft = {
  organizer: "  Forge  ",
  email: " forge@example.com ",
  title: " TypeScript Workshop ",
  format: "onsite",
  venue: " Bengaluru ",
  summary: " Practical session ",
  registrationCloses: "2024-02-29"
};
const before = JSON.stringify(valid);
const success = buildWorkshopSubmission(valid, "2024-02-29");
assert(success.ok === true, "valid boundary-equal date succeeds");
equal(success.value.organizer, "Forge", "organizer trimmed");
equal(success.value.email, "forge@example.com", "email trimmed");
equal(success.value.title, "TypeScript Workshop", "title trimmed");
equal(success.value.format, "onsite", "format retained");
equal(success.value.venue, "Bengaluru", "onsite venue trimmed");
equal(success.value.summary, "Practical session", "summary trimmed");
equal(success.value.registrationCloses, "2024-02-29", "date retained");
equal(JSON.stringify(valid), before, "input not mutated");
assert(success.value !== valid, "submission does not alias input");

const online = buildWorkshopSubmission({ ...valid, format: "online", venue: " Anywhere " }, "2024-02-28");
assert(online.ok === true && online.value.venue === "Remote", "online venue normalizes to Remote");
const blankOnlineVenue = errorsOf(buildWorkshopSubmission({ ...valid, format: "online", venue: "   " }, "2024-02-28"));
equal(blankOnlineVenue.length, 1, "all string fields, including online venue, must be nonblank");

const organizerError = oneError({ ...valid, organizer: " " }, "2024-01-01", "organizer error");
const emailError = oneError({ ...valid, email: "a@@b" }, "2024-01-01", "email error");
const titleError = oneError({ ...valid, title: "" }, "2024-01-01", "title error");
const formatError = oneError({ ...valid, format: "hybrid" as WorkshopDraft["format"] }, "2024-01-01", "format error");
const venueError = oneError({ ...valid, venue: "\t" }, "2024-01-01", "venue error");
const summaryError = oneError({ ...valid, summary: " " }, "2024-01-01", "summary error");
const closeError = oneError({ ...valid, registrationCloses: "2023-12-31" }, "2024-01-01", "registration date error");
const earliestError = oneError(valid, "2024-02-30", "earliest date error");

const allInvalid = {
  organizer: " ", email: "a@@b", title: "", format: "hybrid",
  venue: " ", summary: " ", registrationCloses: "not-a-date"
} as unknown as WorkshopDraft;
const ordered = errorsOf(buildWorkshopSubmission(allInvalid, "2023-02-29"));
const expected = [organizerError, emailError, titleError, formatError, venueError, summaryError, closeError, earliestError];
equal(ordered.length, expected.length, "one unique error per invalid field");
expected.forEach((error, index) => equal(ordered[index], error, `validation order ${index}`));
equal(new Set(ordered).size, ordered.length, "errors are unique");

for (const email of ["@domain", "local@", "local@@domain", "nodomain"] as const) {
  errorsOf(buildWorkshopSubmission({ ...valid, email }, "2024-01-01"));
}
for (const date of ["2023-02-29", "2024-04-31", "2024-2-09", "2024-01-01x"] as const) {
  errorsOf(buildWorkshopSubmission({ ...valid, registrationCloses: date }, "2024-01-01"));
}

const year0099 = buildWorkshopSubmission(
  { ...valid, registrationCloses: "0099-12-31" },
  "0099-12-31"
);
assert(year0099.ok === true, "four-digit year 0099 is valid");
const year0096Leap = buildWorkshopSubmission(
  { ...valid, registrationCloses: "0096-02-29" },
  "0096-02-29"
);
assert(year0096Leap.ok === true, "year 0096 is a leap year");
errorsOf(buildWorkshopSubmission(
  { ...valid, registrationCloses: "1900-02-29" },
  "1900-01-01"
));
const centuryLeap = buildWorkshopSubmission(
  { ...valid, registrationCloses: "2000-02-29" },
  "2000-02-29"
);
assert(centuryLeap.ok === true, "Gregorian century divisible by 400 is leap year");

for (const field of ["organizer", "email", "title", "venue", "summary", "registrationCloses"] as const) {
  const malformed = { ...valid, [field]: 7 } as unknown as WorkshopDraft;
  errorsOf(buildWorkshopSubmission(malformed, "2024-01-01"));
}

